import yaml
import numpy as np
from scipy import stats

with open('registry.yaml', 'r') as f:
    reg = yaml.safe_load(f)

exps = reg.get('experiments', {})

# Collect all successful experiments with SR metrics
def get_sr(exp):
    """Extract success rate from experiment metrics."""
    m = exp.get('metrics', {})
    if not m:
        return None
    # Various naming conventions
    for key in ['success_rate', 'overall_success_rate', 'SR', 'overall_sr']:
        if key in m:
            val = m[key]
            # Some stored as fraction (0.xx), some as percentage (xx.x)
            if isinstance(val, (int, float)):
                return val if val <= 1.0 else val / 100.0
    return None

def get_trigger(exp):
    m = exp.get('metrics', {})
    if not m:
        return None
    return m.get('trigger_rate', None)

# Build lookup: (suite, mode, seed) -> SR
# We need to identify the "canonical" experiment for each combination
# Priority: supp-era (20 rollouts) > earlier versions

results = {}  # (suite, mode, seed) -> {'sr': float, 'exp_id': str, 'trigger': float}

suites = ['spatial', 'goal', 'object', 'long']
modes = ['vla_only', 'adaptive', 'crm']

for exp_id, exp in exps.items():
    if exp.get('conclusion') not in ('success', 'negative'):
        continue
    sr = get_sr(exp)
    if sr is None:
        continue

    spec = exp.get('spec', {})
    m = exp.get('metrics', {})
    hypothesis = exp.get('hypothesis', '')
    cmd = spec.get('command', '')

    # Skip non-SmolVLA experiments (pi05, a1, openvla, lerobot)
    if 'pi05' in exp_id or 'pi0.5' in exp_id or 'a1' in exp_id or 'openvla' in exp_id or 'lerobot' in exp_id:
        continue
    if '--model pi05' in cmd or 'model_name' in spec and spec.get('model_name', '') in ('pi05', 'pi0.5', 'pi05_libero_finetuned'):
        continue

    # Determine suite
    suite = None
    for s in suites:
        if s in exp_id.lower() or s in cmd.lower() or m.get('benchmark') == s:
            suite = s
            break
    if not suite:
        # Try from spec
        benchmark = spec.get('benchmark', '') or m.get('benchmark', '')
        if benchmark:
            suite = benchmark.lower()
    if suite not in suites:
        continue

    # Determine mode
    mode = None
    if 'adapt' in exp_id or 'adaptive' in cmd:
        mode = 'adaptive'
    elif 'crm' in exp_id and 'obs' in exp_id:
        mode = 'crm'
    elif 'crm_obs_only' in cmd or 'crm-norm' in exp_id:
        mode = 'crm'  
    elif 'vla_only' in exp_id or 'vla-only' in exp_id or '--mode vla_only' in cmd:
        mode = 'vla_only'
    elif 'k2mean' in exp_id or 'baseline_mode mean' in cmd:
        continue  # K2mean is a different baseline, skip
    elif 'reconvla' in exp_id:
        continue  # ReconVLA is a different baseline
    elif 'perdof' in exp_id:
        continue  # per-DOF is a different CRM variant
    elif 'scalar' in exp_id:
        continue
    elif 'direct-correction' in exp_id:
        continue
    elif 'random-selection' in exp_id:
        continue
    elif 'argmin' in exp_id:
        continue

    if mode is None:
        continue

    # Determine seed
    seed = None
    # From metrics
    seed = m.get('seed', spec.get('seed'))
    if seed is None:
        # From exp_id
        import re
        seed_match = re.search(r's(?:eed)?(\d+)', exp_id)
        if seed_match:
            seed = int(seed_match.group(1))
    if seed is None:
        # From command
        seed_match = re.search(r'--seed\s+(\d+)', cmd)
        if seed_match:
            seed = int(seed_match.group(1))
    if seed is None:
        continue
    seed = int(seed)

    # Filter: only seeds 42-49 for the paper table
    if seed < 42 or seed > 49:
        continue

    # Check rollout count - prefer 20 rollouts (200 total) over 10 (100 total)
    total = m.get('total', m.get('total_rollouts', 0))
    n_rollouts = m.get('n_rollouts', spec.get('n_rollouts', 0))

    key = (suite, mode, seed)

    # Prefer supp-era (20 rollouts) experiments
    is_supp = 'supp' in exp_id
    existing = results.get(key)

    if existing is None:
        results[key] = {'sr': sr, 'exp_id': exp_id, 'trigger': get_trigger(exp), 'is_supp': is_supp, 'total': total}
    else:
        # Prefer supp-era over non-supp
        if is_supp and not existing['is_supp']:
            results[key] = {'sr': sr, 'exp_id': exp_id, 'trigger': get_trigger(exp), 'is_supp': is_supp, 'total': total}
        elif is_supp == existing['is_supp']:
            # Same era - prefer higher rollout count, or more recent
            if total and existing['total'] and total > existing['total']:
                results[key] = {'sr': sr, 'exp_id': exp_id, 'trigger': get_trigger(exp), 'is_supp': is_supp, 'total': total}

# Print collected data
print("=" * 80)
print("COLLECTED DATA (suite, mode, seed) -> SR")
print("=" * 80)
for suite in suites:
    for mode in modes:
        seeds_data = []
        for seed in range(42, 50):
            key = (suite, mode, seed)
            if key in results:
                r = results[key]
                seeds_data.append((seed, r['sr'], r['exp_id'], r.get('trigger')))
        if seeds_data:
            print(f"\n{suite.upper()} - {mode}:")
            for seed, sr, eid, trig in seeds_data:
                trig_str = f" trigger={trig:.3f}" if trig else ""
                print(f"  s{seed}: {sr*100:.1f}%{trig_str}  ({eid})")

# Compute Table 1
print("\n" + "=" * 80)
print("TABLE 1 — 8-seed (where available)")
print("=" * 80)

table_data = {}
for suite in suites:
    table_data[suite] = {}
    for mode in modes:
        srs = []
        seeds_used = []
        for seed in range(42, 50):
            key = (suite, mode, seed)
            if key in results:
                srs.append(results[key]['sr'])
                seeds_used.append(seed)
        if srs:
            mean = np.mean(srs) * 100
            std = np.std(srs, ddof=1) * 100 if len(srs) > 1 else 0
            table_data[suite][mode] = {
                'mean': mean, 'std': std, 'n': len(srs),
                'srs': srs, 'seeds': seeds_used
            }

# Print markdown table
print("\n| Suite | VLA-only | CRM | Adaptive | Δ(A-V) | Δ(A-C) |")
print("|-------|---------|-----|----------|--------|--------|")
for suite in suites:
    row = f"| {suite.capitalize()} |"
    for mode in ['vla_only', 'crm', 'adaptive']:
        d = table_data.get(suite, {}).get(mode)
        if d:
            row += f" {d['mean']:.1f}±{d['std']:.1f}({d['n']}s) |"
        else:
            row += " — |"
    # Deltas
    a = table_data.get(suite, {}).get('adaptive')
    v = table_data.get(suite, {}).get('vla_only')
    c = table_data.get(suite, {}).get('crm')
    if a and v:
        row += f" {a['mean']-v['mean']:+.1f}pp |"
    else:
        row += " — |"
    if a and c:
        row += f" {a['mean']-c['mean']:+.1f}pp |"
    else:
        row += " — |"
    print(row)

# Paired t-tests
print("\n" + "=" * 80)
print("PAIRED T-TESTS")
print("=" * 80)

for suite in suites:
    print(f"\n--- {suite.upper()} ---")

    # Adaptive vs VLA-only
    a_data = table_data.get(suite, {}).get('adaptive')
    v_data = table_data.get(suite, {}).get('vla_only')
    if a_data and v_data:
        # Find matched seeds
        matched_a = []
        matched_v = []
        matched_seeds = []
        for seed in range(42, 50):
            ka = (suite, 'adaptive', seed)
            kv = (suite, 'vla_only', seed)
            if ka in results and kv in results:
                matched_a.append(results[ka]['sr'])
                matched_v.append(results[kv]['sr'])
                matched_seeds.append(seed)
        if len(matched_a) >= 2:
            deltas = [a - v for a, v in zip(matched_a, matched_v)]
            mean_delta = np.mean(deltas) * 100
            t_stat, p_val = stats.ttest_rel(matched_a, matched_v)
            print(f"  Δ(A-V): {mean_delta:+.2f}pp, t={t_stat:.3f}, p={p_val:.4f}, n={len(matched_a)} matched seeds {matched_seeds}")
            for s, a, v in zip(matched_seeds, matched_a, matched_v):
                print(f"    s{s}: A={a*100:.1f}% V={v*100:.1f}% Δ={((a-v)*100):+.1f}pp")
        else:
            print(f"  Δ(A-V): insufficient matched seeds ({len(matched_a)})")

    # Adaptive vs CRM
    c_data = table_data.get(suite, {}).get('crm')
    if a_data and c_data:
        matched_a = []
        matched_c = []
        matched_seeds = []
        for seed in range(42, 50):
            ka = (suite, 'adaptive', seed)
            kc = (suite, 'crm', seed)
            if ka in results and kc in results:
                matched_a.append(results[ka]['sr'])
                matched_c.append(results[kc]['sr'])
                matched_seeds.append(seed)
        if len(matched_a) >= 2:
            deltas = [a - c for a, c in zip(matched_a, matched_c)]
            mean_delta = np.mean(deltas) * 100
            t_stat, p_val = stats.ttest_rel(matched_a, matched_c)
            print(f"  Δ(A-C): {mean_delta:+.2f}pp, t={t_stat:.3f}, p={p_val:.4f}, n={len(matched_a)} matched seeds {matched_seeds}")
        else:
            print(f"  Δ(A-C): insufficient matched seeds ({len(matched_a)})")

